Certainly! Below is an example of a complex smart contract written in Solidity, the programming language used for Ethereum smart contracts. This contract is designed to facilitate a decentralized voting system with multiple features such as voter registration, candidate registration, voting, and result tallying.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Voter {
        bool isRegistered;
        bool hasVoted;
        uint256 vote;
    }

    struct Candidate {
        string name;
        uint256 voteCount;
    }

    address public owner;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    uint256 public votingEnd;
    bool public votingActive;

    event VoterRegistered(address indexed voter);
    event VoterVoted(address indexed voter, uint256 candidateIndex);
    event CandidateRegistered(string name);
    event VotingEnded();

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action.");
        _;
    }

    modifier onlyDuringVoting() {
        require(votingActive, "Voting is not active.");
        _;
    }

    constructor() {
        owner = msg.sender;
        votingActive = true;
    }

    function registerVoter(address _voter) public onlyOwner {
        require(!voters[_voter].isRegistered, "Voter is already registered.");
        voters[_voter] = Voter(true, false, 0);
        emit VoterRegistered(_voter);
    }

    function registerCandidate(string memory _name) public onlyOwner {
        candidates.push(Candidate(_name, 0));
        emit CandidateRegistered(_name);
    }

    function startVoting(uint256 _duration) public onlyOwner {
        require(votingActive, "Voting is already active.");
        require(_duration > 0, "Duration must be greater than zero.");
        votingEnd = block.timestamp + _duration;
        votingActive = false;
    }

    function endVoting() public onlyOwner {
        require(!votingActive, "Voting is not active.");
        votingActive = true;
        emit VotingEnded();
    }

    function vote(uint256 _candidateIndex) public onlyDuringVoting {
        require(!voters[msg.sender].hasVoted, "Voter has already voted.");
        require(_candidateIndex < candidates.length, "Invalid candidate index.");
        voters[msg.sender].hasVoted = true;
        voters[msg.sender].vote = _candidateIndex;
        candidates[_candidateIndex].voteCount += 1;
        emit VoterVoted(msg.sender, _candidateIndex);
    }

    function getCandidate(uint256 _index) public view returns (string memory, uint256) {
        require(_index < candidates.length, "Invalid candidate index.");
        Candidate memory candidate = candidates[_index];
        return (candidate.name, candidate.voteCount);
    }

    function getVoter(address _voter) public view returns (bool, bool, uint256) {
        return (voters[_voter].isRegistered, voters[_voter].hasVoted, voters[_voter].vote);
    }
}
```

This smart contract includes the following features:
- Voter and Candidate structures to store relevant information.
- Functions to register voters and candidates, and to start and end the voting period.
- A voting function that allows registered voters to vote for candidates during the active voting period.
- Events to emit notifications for various actions.
- Modifiers to restrict certain actions to the contract owner and to ensure actions are only performed during the active voting period.

This contract can be further expanded with additional features such as candidate withdrawal, vote delegation, and more sophisticated access control mechanisms.

